-- 2147483648, 2147483648, 3
-- 2147483648, NULL, NULL
SELECT DRIVERS.FORENAME, DRIVERS.SURNAME, RESULTS.POINTS FROM RESULTS INNER JOIN DRIVERS ON RESULTS.DRIVERID = DRIVERS.DRIVERID INNER JOIN RACES ON RESULTS.RACEID = RACES.RACEID WHERE RACES.YEAR = 2017 AND RACES.NAME = 'CHINESE GRAND PRIX' ORDER BY RESULTS.POINTS DESC LIMIT 3;
-- ----------sql2------------
SELECT T3.FORENAME, T3.SURNAME, T2.POINTS FROM RACES AS T1 INNER JOIN DRIVERSTANDINGS AS T2 ON T2.RACEID = T1.RACEID INNER JOIN DRIVERS AS T3 ON T3.DRIVERID = T2.DRIVERID WHERE T1.NAME = 'CHINESE GRAND PRIX' AND T1.YEAR = 2017 ORDER BY T2.POINTS DESC LIMIT 3;

