-- ----------sql1------------
-- 2147483649, 2147483649, 2147483649, 26125
SELECT DRIVERS.FORENAME, DRIVERS.SURNAME, DRIVERS.NATIONALITY, MAX(DRIVERSTANDINGS.POINTS) AS MAX_POINTS FROM DRIVERS INNER JOIN DRIVERSTANDINGS ON DRIVERS.DRIVERID = DRIVERSTANDINGS.DRIVERID GROUP BY DRIVERS.FORENAME, DRIVERS.SURNAME, DRIVERS.NATIONALITY ORDER BY COUNT(DRIVERSTANDINGS.WINS) DESC LIMIT 1;
-- ----------sql2------------
-- 2147483649, 2147483649, 2147483649, NULL
SELECT T1.FORENAME, T1.SURNAME, T1.NATIONALITY, MAX(T2.POINTS) FROM DRIVERS AS T1 INNER JOIN DRIVERSTANDINGS AS T2 ON T2.DRIVERID = T1.DRIVERID WHERE T2.WINS >= 1 GROUP BY T1.FORENAME, T1.SURNAME, T1.NATIONALITY ORDER BY COUNT(T2.WINS) DESC LIMIT 1;

